function checkinSalvarReuniao() {
  const reuniao = {
    id: Date.now(),
    data: document.getElementById('checkin-ci-data').value,
    hora: document.getElementById('checkin-ci-hora').value,
    assuntos: [...checkinAssuntos]
  };
  checkinReunioes.push(reuniao);
  checkinS.set('reunioes', checkinReunioes);
  checkinNotify('Reunião salva!');
}

// Salvar a reunião fecha o dia: os status passam a valer como registrados.
// Antes isto só guardava um retrato aqui no navegador — a planilha continuava
// com os status antigos, e o botão Atualizar trazia os antigos de volta por
// cima. Agora a gravação vai também para a planilha e o dia fica travado.
async function checkinSalvarReuniao() {
  const hoje = checkinDataDeHoje();
  const reuniao = {
    id: Date.now(),
    data: document.getElementById('checkin-ci-data').value,
    hora: document.getElementById('checkin-ci-hora').value,
    assuntos: [...checkinAssuntos]
  };
  checkinReunioes.push(reuniao);
  checkinS.set('reunioes', checkinReunioes);

  // Trava o dia ANTES de falar com a rede: mesmo que a internet caia, o
  // Atualizar já não desfaz o que acabou de ser registrado.
  checkinAssuntos.forEach(a => { a.statusTravadoEm = hoje; });
  checkinS.set('assuntos', checkinAssuntos);
  checkinNotify('Reunião salva!');

  // Leva os status alterados para a planilha, para que ela pare de devolver
  // o valor antigo. Só sobem os que mudaram aqui e ainda não subiram.
  const pendentes = checkinAssuntos.filter(a => a.statusLocalEm && a.id);
  if (!pendentes.length) return;

  let enviados = 0;
  for (const a of pendentes) {
    const ok = await checkinEnviarStatus(a.id, a.status);
    if (ok) { delete a.statusLocalEm; enviados++; }
  }
  checkinS.set('assuntos', checkinAssuntos);

  if (enviados === pendentes.length) {
    checkinNotify('✅ Reunião salva e status gravados na planilha', '#2d6a40');
  } else {
    // O dado local está seguro (travado); só a planilha ficou para trás.
    checkinNotify('⚠️ Reunião salva aqui, mas ' + (pendentes.length - enviados) +
      ' status não foram para a planilha. Toque em Atualizar quando tiver internet.', '#c99500');
  }
}

// Data de hoje no formato AAAA-MM-DD, no fuso do aparelho.
function checkinDataDeHoje() {
  const d = new Date();
  const tz = d.getTimezoneOffset() * 60000;
  return new Date(d - tz).toISOString().slice(0, 10);
}

// Envia um status para a planilha. Devolve true só se a planilha confirmar.
async function checkinEnviarStatus(id, status) {
  try {
    const resp = await fetch(APPS_SCRIPT_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({ path: 'pauta', action: 'atualizar-status', id: id, status: status })
    });
    const data = await resp.json().catch(() => null);
    return !!(data && data.status === 'ok');
  } catch (e) {
    console.warn('Check-in: status não enviado para a planilha:', e.message);
    return false;
  }
}

