async function checkinCarregarDaPlanilha() {
  checkinNotify('Atualizando da planilha...', 'var(--blue)');
  // Primeiro EMPURRA o que mudou aqui e ainda não subiu (por exemplo, uma
  // reunião salva sem internet), só depois BUSCA. Na ordem inversa a
  // planilha devolveria o valor velho por cima do novo. Sem este reenvio, o
  // pendente ficaria preso até a próxima reunião salva — e quando a trava do
  // dia vencesse, o status antigo voltaria.
  await checkinEnviarStatusPendentes();
  await Promise.all([
    checkinCarregarAssuntosDaPauta(),
    checkinCarregarHistoricoDoServidor()
  ]);
}

// Reenvia à planilha os status que mudaram aqui e ainda não foram aceitos.
async function checkinEnviarStatusPendentes() {
  checkinAssuntos = checkinS.get('assuntos') || checkinAssuntos;
  const pendentes = checkinAssuntos.filter(a => a.statusLocalEm && a.id);
  if (!pendentes.length) return;
  let enviados = 0;
  for (const a of pendentes) {
    if (await checkinEnviarStatus(a.id, a.status)) { delete a.statusLocalEm; enviados++; }
  }
  checkinS.set('assuntos', checkinAssuntos);
  if (enviados) checkinNotify('✅ ' + enviados + ' status pendente(s) enviado(s) à planilha', '#2d6a40');
}
